'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');
const {test}=require('node:test');
const script=/<script>([\s\S]*?)<\/script>/.exec(fs.readFileSync(path.join(__dirname,'..','admin_ui.go'),'utf8'))[1];
function grab(name){let start=script.indexOf('function '+name+'(');assert.ok(start>=0,name);if(script.slice(start-6,start)==='async ')start-=6;let depth=0;for(let i=script.indexOf('{',start);i<script.length;i++){if(script[i]==='{')depth++;if(script[i]==='}'&&--depth===0)return script.slice(start,i+1);}throw Error(name);}
const id='정책 +%2F?&#/', hash=value=>'#/safety?'+new URLSearchParams({policy_id:value??id});
const row=(changes={})=>({id,name:'selected policy',description:'selected description',enabled:false,priority:3,rollout_percent:0,created_at:'2026-11-18T01:00:00Z',updated_at:'2026-11-18T02:00:00Z',rules:[{id:'rule-one',policy_id:id,name:'selected rule',enabled:true,priority:2,conditions:{team_id:'team-one',model:'selected-model'},actions:{require_approval:true,deny_models:['denied-model']},created_at:'2026-11-18T01:00:00Z',updated_at:'2026-11-18T02:00:00Z'}],...changes});
function harness(){
 const nodes={},calls=[];const node=id=>nodes[id]??(nodes[id]={innerHTML:'',textContent:'',listeners:{},focus(){},addEventListener(k,fn){this.listeners[k]=fn}});
 const h={URLSearchParams,TextEncoder,document:{getElementById:node},location:{hash:hash()},calls,nodes,reply:async()=>({policies:[row(),row({id:'other-policy',name:'OTHER_POLICY'})]}),section:(title,html)=>title+html};h.window=h;vm.createContext(h);
 vm.runInContext('let legacyRouteGeneration=1,authEpoch=1;function authCurrent(epoch){return epoch===authEpoch}async function api(url,opts){calls.push({url,opts});return reply(url,opts)}function route(){globalThis.retries=(globalThis.retries||0)+1}'+['legacyPolicyTarget','legacyDetailTextPages','escapeHTML','renderLegacyPolicyDetail','renderSafety'].map(grab).join('\n')+'globalThis.retire=kind=>{if(kind==="auth")authEpoch++;else if(kind==="route")legacyRouteGeneration++;else location.hash="#/other";document.getElementById("view").innerHTML="NEW";};',h);
 h.open=async(value=id)=>{h.location.hash=hash(value);await h.renderLegacyPolicyDetail();};h.click=id=>h.nodes[id].listeners.click();return h;
}
test('exact selected policy preserves every saved rule and effective rollout without mutations',async()=>{
 const h=harness();await h.open();assert.equal(h.calls.length,1);assert.equal(h.calls[0].url,'/admin/policies');assert.equal(h.calls[0].opts.method,undefined);assert.equal(h.calls[0].opts.cache,'no-store');
 const html=h.nodes.view.innerHTML;for(const value of ['selected policy','selected description','사용 중지','100%','selected rule','team-one','selected-model','require_approval','denied-model'])assert.ok(html.includes(value),value);
 assert.ok(!/OTHER_POLICY|<input|<form|onclick=/.test(html));
});
for(const selected of ['__proto__','😀'.repeat(512),'정책 +%2F?&#/'])test('exact policy identity '+selected.slice(0,12),async()=>{const h=harness();h.reply=async()=>({policies:[row({id:selected,rules:[]})]});await h.open(selected);assert.ok(h.nodes.view.innerHTML.includes('selected policy'));});
for(const raw of ['#/safety?policy_id=','#/safety?policy_id=x&policy_id=y','#/safety?policy_id=x&other=y','#/safety?policy_id=%ED%A0%80','#/safety?policy_id=%ZZ','#/safety?policy_id=%00','#/safety?policy_id=%20trim','#/safety?policy_id='+'a'.repeat(513)])test('reject invalid selection without API '+raw.slice(0,55),async()=>{const h=harness();h.location.hash=raw;await h.renderLegacyPolicyDetail();assert.match(h.nodes.view.innerHTML,/주소가 올바르지/);assert.equal(h.calls.length,0);});
test('missing selected policy stays distinct from errors and never shows another policy',async()=>{const h=harness();await h.open('missing');assert.match(h.nodes.view.innerHTML,/찾을 수 없습니다/);assert.ok(!h.nodes.view.innerHTML.includes('OTHER_POLICY'));h.click('legacy-policy-retry');assert.equal(h.retries,1);});
for(const policies of [[row(),row()], [row({rules:[{...row().rules[0],policy_id:'foreign'}]})], [row({enabled:'true'})]])test('ambiguous or invalid response does not render policy values '+JSON.stringify(policies).slice(0,45),async()=>{const h=harness();h.reply=async()=>({policies});await h.open();assert.match(h.nodes.view.innerHTML,/불러오지 못했습니다/);assert.ok(!h.nodes.view.innerHTML.includes('selected description'));});
test('stored content is escaped and unknown top-level fields are not shown',async()=>{const h=harness();h.reply=async()=>({policies:[row({name:'<script>bad</script>',description:'<img src=x>',unknown:'PRIVATE_UNKNOWN',rules:[{...row().rules[0],conditions:{text:'<svg onload=bad>'}}]})]});await h.open();const html=h.nodes.view.innerHTML;assert.match(html,/&lt;script&gt;/);assert.match(html,/&lt;svg/);assert.ok(!/<script>|<img|<svg|PRIVATE_UNKNOWN/.test(html));});
test('long UTF8 description and rule definitions are fully paged without new reads',async()=>{
 const h=harness(),description='가'.repeat(16383)+'😀description-tail';const policy=row({description,rules:Array.from({length:128},(_,i)=>({...row().rules[0],id:'rule-'+i,name:'rule-'+i,conditions:{value:'문'.repeat(400)+i}}))});h.reply=async()=>({policies:[policy]});await h.open();
 for(const [key,text] of [['description',description],['rules',JSON.stringify(policy.rules,null,2)]]){let shown='';const pages=h.legacyDetailTextPages(text);for(let i=0;i<pages.length;i++){const part=new RegExp('<pre id="legacy-policy-'+key+'"[^>]*>([\\s\\S]*?)</pre>').exec(h.nodes.view.innerHTML)[1];assert.ok(part.length<40000);shown+=part.replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&');if(i+1<pages.length)h.click('legacy-policy-'+key+'-next');}assert.equal(shown,text);}assert.equal(h.calls.length,1);
});
for(const kind of ['auth','route','hash']){
 test('late selected response cannot repaint after '+kind,async()=>{const h=harness();let done;h.reply=()=>new Promise(r=>done=r);const pending=h.open();h.retire(kind);done({policies:[row()]});await pending;assert.equal(h.nodes.view.innerHTML,'NEW');});
 test('retired controls cannot retry after '+kind,async()=>{const h=harness();await h.open();h.retire(kind);h.click('legacy-policy-retry');assert.equal(h.retries,undefined);assert.equal(h.nodes.view.innerHTML,'NEW');});
 test('old safety overview cannot replace a new selection after '+kind,async()=>{const h=harness();let done;const gate=new Promise(r=>done=r);h.reply=()=>gate;const pending=h.renderSafety();h.retire(kind);done({policies:[row()]});await pending;assert.equal(h.nodes.view.innerHTML,'NEW');assert.equal(h.safetyPolicies,undefined);});
}
test('errors do not expose server body or old policy data',async()=>{const h=harness();h.reply=async()=>{throw Error('PRIVATE_ERROR_BODY')};await h.open();assert.match(h.nodes.view.innerHTML,/불러오지 못했습니다/);assert.ok(!h.nodes.view.innerHTML.includes('PRIVATE_ERROR_BODY'));});
